const colors={VIG:'#e7dba2',ESP:'#d4aeec',ARC:'#8cd8f4',BAS:'#9dc9dc',RUP:'#ffbb91',DUE:'#e9c7a6',LAS:'#b8b1fa'};
export function skillArt(skill,id,ultimate=false){const c=colors[id]||'#b4d9e7',k=skill.kind;let shape='';if(['shot','mark','horizon'].includes(k))shape='<path d="M8 32L32 8M22 8H32V18M8 23L17 32M7 33L15 31 9 25"/><path d="M10 9Q33 16 30 31" opacity=".55"/>';else if(['spell','storm','nova','eclipse','rune','amp'].includes(k))shape='<path d="M22 4L12 20H21L16 36 30 16H21Z" fill="currentColor"/><circle cx="20" cy="20" r="15" opacity=".4"/><path d="M4 21H9M31 21H37M20 4V8M20 33V37"/>';else if(['barrier','guard','fortress','iron','taunt','break'].includes(k))shape='<path d="M8 9L20 5 32 9 30 25 20 35 10 25Z"/><path d="M20 10V28M13 18H27"/>';else if(['haste','backstep','blink','dash','cloak'].includes(k))shape='<path d="M8 12L17 20 8 28M19 9L31 20 19 31M5 5L11 7M4 35L10 33"/>';else if(['crit','night','dance','parry'].includes(k))shape='<path d="M20 5L25 15 36 20 25 25 20 35 15 25 4 20 15 15Z"/><circle cx="20" cy="20" r="6"/>';else shape='<path d="M11 31L28 7 33 5 33 12 16 34ZM7 26L20 35M9 31L5 37"/><path d="M7 7L29 34M4 5L9 6 8 12M24 33L34 27" opacity=".7"/>';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" aria-hidden="true" style="color:${ultimate?'#fce4ad':c}"><circle cx="20" cy="20" r="18" fill="currentColor" opacity=".05"/><g stroke="currentColor" fill="none" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${shape}${ultimate?'<circle cx="20" cy="20" r="18" stroke-width=".6"/>':''}</g></svg>`;}
